"""Finite stress tests for the congruence and power-band cover. Python 3 standard library."""
from fractions import Fraction
from itertools import product
import argparse
import json
from pathlib import Path


def quotient_order(a, modulus):
    """Order of an odd residue modulo the subgroup generated by −1."""
    residue, order = a % modulus, 1
    while residue not in {1, modulus - 1}:
        residue = residue * residue % modulus
        order *= 2
        if order > modulus:
            raise AssertionError("Repeated squaring failed to reach +1 or -1.")
    return order


def check_moduli():
    comparisons = covering_counts = 0
    for r in range(1, 10):
        full = 2 ** (r + 2)
        odds = range(1, full, 2)
        orders = {n: quotient_order(n, full) for n in odds}
        for J in sorted({1, 2, 3, 5, 6, 7, 2**r-1, 2**r, 2**r+1}):
            j = min(r, J.bit_length()-1)
            modulus = 2 ** (r + 2-j)
            assert Fraction(2, modulus) <= Fraction(J, 2*(2**r))
            for n, order in orders.items():
                assert (order <= J) == (n % modulus in (1, modulus-1))
                comparisons += 1
            for Y in (Fraction(7, 2), Fraction(full), Fraction(2*full+3, 2),
                      Fraction(9*full+1, 3)):
                amount = sum(n % modulus in (1, modulus-1)
                             for n in range(1, (Y.numerator + Y.denominator - 1) // Y.denominator))
                assert amount <= 2*Y/modulus + 2
                covering_counts += 1
    return {"rank_exponent_range": [1, 9], "orders_compared": comparisons,
            "interval_counts_checked": covering_counts}


def check_bands():
    cases = hits = higher = 0
    for Y, rho in product((Fraction(7), Fraction(8), Fraction(15, 2), Fraction(16),
                           Fraction(25), Fraction(64), Fraction(199, 2), Fraction(1000)),
                          (Fraction(0), Fraction(1, 1000), Fraction(1, 20),
                           Fraction(1, 3), Fraction(1, 2))):
        low, high = Y*(1-rho), Y*(1+rho)
        linear = []
        for n in range(2, (Y.numerator + Y.denominator - 1) // Y.denominator):
            power, degree = n, 1
            while power <= high:
                if low <= power:
                    hits += 1
                    if degree == 1:
                        assert Y*(1-rho) <= n < Y
                        linear.append(n)
                    else:
                        assert n*n <= high
                        higher += 1
                degree += 1
                power *= n
        assert len(linear) <= rho*Y+1
        cases += 1
    # Omitting higher powers misses p=5 at a band of zero width.
    assert 5 < 25 and 5*5 == 25
    # −1 has signed order one and ordinary order two.
    assert quotient_order(15, 16) == 1 and 15 % 16 != 1
    return {"cutoff_width_pairs": cases, "power_hits": hits, "higher_degree_hits": higher,
            "negative_controls": ["p=5 squared at cutoff 25", "signed order of 15 mod 16"]}


def check_exponents():
    e100 = Fraction(1, 100)
    rank_lower = 8 - 2 * e100
    order_decay = rank_lower - Fraction(1, 4)
    rho_first = 8 + e100 - Fraction(1, 8) + 1 + (1 + e100) - (10 - e100)
    rho_second = 1 + e100 - (10 - e100)
    assert (rank_lower, order_decay, rho_first, rho_second) == (
        Fraction(399, 50), Fraction(773, 100), -Fraction(19, 200), -Fraction(449, 50))
    assert 2 + order_decay / 52 < Fraction(5, 2)
    return {"dyadic_rank_excess": str(rank_lower), "order_decay_excess": str(order_decay),
            "first_rho_epsilon": str(rho_first), "second_rho_epsilon": str(rho_second)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", type=Path)
    args = parser.parse_args()
    result = {"signed_order": check_moduli(), "power_band": check_bands(),
              "family_exponents": check_exponents()}
    if args.check:
        if json.loads(args.check.read_text()) != result:
            raise SystemExit("Stored output differs.")
        print("Reproduced finite dropped-prime geometry controls.")
    else:
        print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
